import{_ as e,C as n,c as i,o as r,a0 as t,b as s,w as a,a as l,G as h,a1 as u}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Technische Beratung","description":"","frontmatter":{},"headers":[],"relativePath":"de/technical/index.md","filePath":"de/technical/index.md"}');const d=e({name:"de/technical/index.md"},[["render",function(e,c,d,o,g,m){const f=n("Mermaid");return r(),i("div",null,[c[2]||(c[2]=t('<h1 id="technische-beratung" tabindex="-1">Technische Beratung <a class="header-anchor" href="#technische-beratung" aria-label="Permalink to &quot;Technische Beratung&quot;">​</a></h1><h2 id="eine-anmerkung-zur-technik" tabindex="-1">Eine Anmerkung zur Technik <a class="header-anchor" href="#eine-anmerkung-zur-technik" aria-label="Permalink to &quot;Eine Anmerkung zur Technik&quot;">​</a></h2><p>Unser Hauptaugenmerk liegt zwar auf dem mentalen Spiel und dem Flow-Zustand, aber wir erkennen an, dass die Technik das Fundament ist, auf dem alles andere aufbaut.</p><div class="info custom-block"><p class="custom-block-title">Unsere Philosophie</p><p><strong>Technik ist die Grundlage, aber Flow ist die Grenze.</strong> Um ein Elite-Niveau zu erreichen, braucht man eine solide Technik, aber mentale Meisterschaft ist das, was einen darüber hinausbringt.</p></div>',4)),(r(),s(u,null,{default:a(()=>[h(f,{id:"mermaid-14",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BP%C3%A9tanque-Meisterschaft%5D%20--%3E%20B%5BTechnisches%20Fundament%5D%0A%20%20%20%20A%20--%3E%20C%5BMentales%20Spiel%5D%0A%0A%20%20%20%20B%20--%3E%20D%5BSolide%20Technik%5D%0A%20%20%20%20D%20--%3E%20E%5BPlateau%5D%0A%0A%20%20%20%20C%20--%3E%20F%5BStr%C3%B6mungszustand%5D%0A%20%20%20%20F%20--%3E%20G%5BSpitzenleistung%5D%0A%0A%20%20%20%20B%20--%3E%20C%0A%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A%20%20%20%20style%20G%20fill%3A%23fff4e1%0A"})]),fallback:a(()=>[...c[0]||(c[0]=[l(" Loading... ",-1)])]),_:1})),c[3]||(c[3]=t('<h2 id="der-haufigste-fehler-in-der-technischen-ausbildung" tabindex="-1">Der häufigste Fehler in der technischen Ausbildung <a class="header-anchor" href="#der-haufigste-fehler-in-der-technischen-ausbildung" aria-label="Permalink to &quot;Der häufigste Fehler in der technischen Ausbildung&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Dieser Abschnitt ist für erfahrene Spieler.</p><p>Wenn Sie neu im Pétanque sind, müssen Sie Ihre Grundtechnik natürlich von Grund auf entwickeln – und das ist eine ganz andere Sache.</p><p><strong>Dieser Rat richtet sich an Spieler mit jahrelanger Erfahrung,</strong> die bereits eine etablierte Technik entwickelt haben, die sich natürlich, entspannt und zuverlässig anfühlt. Sie haben Ihren eigenen Wurfstil gefunden. Nun stellt sich die Frage: Wie können Sie sich weiterentwickeln?</p></div><div class="warning custom-block"><p class="custom-block-title">Die häufigste Falle</p><p>Wenn erfahrene Spieler sich verbessern wollen, besinnen sie sich oft auf die Grundlagen – sie optimieren Griff, Armschwung, Abwurfpunkt und Körperhaltung. Stundenlanges Training. Unaufhörliches Feintuning.</p><p><strong>Aber sie haben die wichtigste Frage ausgelassen:</strong> Was genau soll die Boule bewirken?</p></div><p>Bevor du an deiner Technik arbeitest, musst du dir über das <strong>Ergebnis</strong> im Klaren sein, das du erreichen willst. Nicht „Ich will mehr Schläge landen“ oder „Ich will konstanter sein“ – das sind keine Ergebnisse, sondern Wünsche.</p><p>Ein reales Ergebnis sieht folgendermaßen aus:</p><ul><li>&quot;Ich möchte einen hohen Lobball, der innerhalb von 20 cm vom Landepunkt stoppt.&quot;</li><li>„Ich möchte eine rollende Aufnahme, die auf diesem Terrain eine Linkskurve beschreibt.“</li><li>&quot;Ich möchte einen sanften Rückstoß, der die Zielkugel kaum berührt.&quot;</li></ul><p><strong>Erkunden Sie zunächst die <a href="/en/technical/throws">Wurfpalette</a></strong>, um zu verstehen, was möglich ist. Entscheiden Sie dann, welchen Wurf Sie in Ihr Repertoire aufnehmen möchten. Erst dann sollten Sie daran arbeiten, wie sich Arm, Handgelenk und Körper bewegen müssen, um dieses Ergebnis zu erzielen.</p><h2 id="der-richtige-weg-um-an-der-technik-zu-arbeiten" tabindex="-1">Der richtige Weg, um an der Technik zu arbeiten <a class="header-anchor" href="#der-richtige-weg-um-an-der-technik-zu-arbeiten" aria-label="Permalink to &quot;Der richtige Weg, um an der Technik zu arbeiten&quot;">​</a></h2><p>Wir sagen nicht, dass du nie an deinem Arm, Handgelenk, deiner Bewegungsausführung oder deiner Körperhaltung arbeiten solltest. <strong>Technisches Training zur Ausführung ist absolut sinnvoll</strong> – aber es muss dem richtigen Zweck dienen.</p><div class="info custom-block"><p class="custom-block-title">Der richtige Zweck technischer Arbeiten</p><p><strong>Korrekte Absicht:</strong> &quot;Ich möchte einen neuen Wurf zu meinem Repertoire hinzufügen&quot;</p><p><strong>Falsches Ziel:</strong> &quot;Ich möchte mehr Würfe treffen&quot; oder &quot;Ich möchte konstanter sein&quot;</p></div><p>So funktioniert es:</p><ol><li><strong>Erkunden Sie die <a href="/en/technical/throws">Wurfpalette</a></strong> — Finden Sie heraus, welchen Wurf oder welche Technik Sie Ihrem Repertoire hinzufügen möchten.</li><li><strong>Visualisieren Sie das Ergebnis</strong> — Was soll die Boulekugel machen? Welche Flugbahn, Landung, Rotation und welches Verhalten benötigen Sie?</li><li><strong>Dann arbeiten Sie an der Ausführung</strong> – Jetzt können Sie sich auf Arm-, Handgelenk- und Körperhaltung sowie die Freigabe konzentrieren, um dieses spezifische Ergebnis zu erzielen.</li></ol><p>Dieser Ansatz gibt Ihrer technischen Ausbildung <strong>klare Richtung und messbare Fortschritte</strong>. Sie üben nicht einfach nur – Sie erweitern gezielt Ihre Fähigkeiten.</p><div class="tip custom-block"><p class="custom-block-title">Beispiel: Hinzufügen einer Plombée</p><p><strong>Ziel:</strong> Füge deinem Zeige-Repertoire einen Drop Shot (Plombée) hinzu.</p><p><strong>Ergebnisvisualisierung:</strong> Die Boule sollte einen hohen Bogen beschreiben, sanft mit Rückwärtsdrall landen und fast sofort zum Stillstand kommen.</p><p><strong>Technischer Fokus:</strong> Höherer Abwurfpunkt, mehr Handgelenkeinsatz für Rückwärtsdrall, weicherer Griff</p><p><strong>Erfolgsmessung:</strong> Können Sie diesen Wurf ausführen, wann immer Sie es wünschen? Das ist das Ziel.</p></div><h2 id="bessere-schusse-vs-mehr-schusse-den-unterschied-verstehen" tabindex="-1">Bessere Schüsse vs. Mehr Schüsse: Den Unterschied verstehen <a class="header-anchor" href="#bessere-schusse-vs-mehr-schusse-den-unterschied-verstehen" aria-label="Permalink to &quot;Bessere Schüsse vs. Mehr Schüsse: Den Unterschied verstehen&quot;">​</a></h2><p>Es gibt einen entscheidenden Unterschied, den viele Spieler übersehen:</p><div class="tip custom-block"><p class="custom-block-title">Die wichtigste Erkenntnis</p><p><strong>Wenn du bessere Fotos machen willst</strong> → Arbeite an deiner Technik.</p><p><strong>Wenn du mehr Würfe treffen willst</strong> → Arbeite an deiner mentalen Stärke.</p></div><h3 id="was-bedeutet-das" tabindex="-1">Was bedeutet das? <a class="header-anchor" href="#was-bedeutet-das" aria-label="Permalink to &quot;Was bedeutet das?&quot;">​</a></h3><p><strong>Bessere Aufnahmen zu machen</strong> bedeutet, sein technisches Repertoire zu erweitern:</p><ul><li>Hinzufügen neuer Wurfarten (Plombée, Portée, Demi-Portée)</li><li>Verbesserung der Präzision bei bestimmten Schussarten</li><li>Neue Fähigkeiten entwickeln, die Sie derzeit noch nicht besitzen</li><li><strong>Dies erfordert technisches Können und körperliches Training.</strong></li></ul><p><strong>Mehr Würfe zu verwandeln</strong> bedeutet, das umzusetzen, was man bereits kann:</p><ul><li>Die Schläge ausführen, die man im Training bereits schafft</li><li>Konstante Leistung unter Druck</li><li>Vertraue deiner Technik, wenn es darauf ankommt</li><li><strong>Dies erfordert mentales Training und den Zugang zum Flow-Zustand.</strong></li></ul><h3 id="der-realitatscheck" tabindex="-1">Der Realitätscheck <a class="header-anchor" href="#der-realitatscheck" aria-label="Permalink to &quot;Der Realitätscheck&quot;">​</a></h3><p>Fragen Sie sich ehrlich:</p><ul><li>Gelingt dir der Wurf im Training, wenn du entspannt bist? ✅ <strong>Dann beherrschst du die Technik.</strong></li><li>Fällt es dir schwer, im Wettkampf mitzuhalten? ⚠️ <strong>Dann brauchst du mentales Training, nicht mehr technische Übungen.</strong></li></ul><div class="warning custom-block"><p class="custom-block-title">Häufiger Fehler</p><p>Viele erfahrene Spieler verbringen Jahre damit, ihre bereits vorhandene Technik zu verfeinern, dabei müssten sie eigentlich die mentale Stärke entwickeln, diese Technik auch unter Druck umzusetzen.</p><p><strong>Du brauchst keinen besseren Armschwung. Du brauchst einen ruhigeren Geist.</strong></p></div><h3 id="der-weg-nach-vorn" tabindex="-1">Der Weg nach vorn <a class="header-anchor" href="#der-weg-nach-vorn" aria-label="Permalink to &quot;Der Weg nach vorn&quot;">​</a></h3><p><strong>Für bessere Aufnahmen (neue Funktionen):</strong></p><ul><li>Entdecke die <a href="/en/technical/throws">Wurfpalette</a></li><li>Wähle einen bestimmten neuen Wurf aus, den du entwickeln möchtest</li><li>Üben Sie die technische Ausführung</li></ul><p><strong>Für mehr Schüsse (Konstanz unter Druck):</strong></p><ul><li>Arbeit an <a href="/en/education/mental-strength/">Mental Strength</a></li><li>Lerne, wie du auf <a href="/en/education/the-zone/">The Zone</a> zugreifst</li><li>Entwickle <a href="/en/education/mental-strength/pre-shot-routine">Pre-Shot-Routinen</a></li></ul><h2 id="unsere-sichtweise" tabindex="-1">Unsere Sichtweise <a class="header-anchor" href="#unsere-sichtweise" aria-label="Permalink to &quot;Unsere Sichtweise&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Man muss nicht alles beherrschen.</p><p><strong>Sie müssen nicht alle Techniken beherrschen</strong>, aber das Verständnis des gesamten Spektrums an Möglichkeiten hilft Ihnen dabei:</p><ul><li>✅ Wissen, was möglich ist</li><li>✅ Treffen Sie fundierte Entscheidungen darüber, was Sie entwickeln möchten.</li><li>✅ Das Spiel auf einer tieferen Ebene wertschätzen.</li><li>✅ Verstehen, was Spitzenspieler können</li></ul></div>',33)),(r(),s(u,null,{default:a(()=>[h(f,{id:"mermaid-277",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BFachkenntnisse%5D%20--%3E%20B%5BInformierte%20Entscheidungen%5D%0A%20%20%20%20B%20--%3E%20C%5BGezielte%20Entwicklung%5D%0A%20%20%20%20C%20--%3E%20D%5BBeherrschung%20der%20Schl%C3%BCsselkompetenzen%5D%0A%20%20%20%20D%20--%3E%20E%5BZugriff%20auf%20den%20Flusszustand%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:a(()=>[...c[1]||(c[1]=[l(" Loading... ",-1)])]),_:1})),c[4]||(c[4]=t('<div class="info custom-block"><p class="custom-block-title">Das Ziel</p><p>Wenn Sie einen technischen Schwerpunkt haben und Ihr Repertoire erweitern möchten, beschreibt dieser Abschnitt das Endziel – die gesamte Palette an Würfen, die einem Pétanque-Spieler zur Verfügung stehen.</p><p><strong>Denk daran:</strong> Es geht nicht darum, alles zu beherrschen. Es geht darum, über genügend technische Grundlagen zu verfügen, um in den Flow-Zustand zu gelangen und deinem Körper zu ermöglichen, den richtigen Wurf ganz natürlich auszuführen.</p></div><h2 id="themen" tabindex="-1">Themen <a class="header-anchor" href="#themen" aria-label="Permalink to &quot;Themen&quot;">​</a></h2><h3 id="wurfpalette" tabindex="-1"><a href="/en/technical/throws">Wurfpalette</a> <a class="header-anchor" href="#wurfpalette" aria-label="Permalink to &quot;[Wurfpalette](/en/technical/throws)&quot;">​</a></h3><p>Welche Wurftechniken gibt es alle? Ein umfassender Überblick über die technischen Möglichkeiten beim Pétanque.</p><div class="tip custom-block"><p class="custom-block-title">Nach der Technik – was kommt als Nächstes?</p><p>Sobald man über eine solide Technik verfügt, kommt das eigentliche Wachstum von Folgendem:</p><ul><li><strong><a href="/en/education/the-zone/">Die Zone</a></strong> – Zugriff auf Flow-Zustände</li><li><strong><a href="/en/education/mental-strength/">Mentale Stärke</a></strong> – Umgang mit Druck</li><li><strong><a href="/en/education/training/">Trainingsmethoden</a></strong> – Wie man effektiv übt</li></ul></div>',5))])}]]);export{c as __pageData,d as default};
